import six
from abc import ABCMeta, abstractmethod
from taf.internal.managedobject import ManagedObject


@six.add_metaclass(ABCMeta)
class ChannelEmulator(ManagedObject):

    @abstractmethod
    def load_local_system_setting_file(self, path):
        """
        Load local configuration file and transfer it to the channel emulator.

        :param path:  str, local configuration file path
        :return:
        """
        pass

    @abstractmethod
    def load_remote_system_setting_file(self, path):
        """
        Load configuration file on remote pc

        :param path:  str, remote configuration file path
        :return:
        """
        pass

    @abstractmethod
    def query_fading_doppler_frequency(self, channel, path):
        """
        Query the fading doppler frequency.

        :param channel: int, channel number
        :param path: int, path
        :return: str, doppler frequency
        """
        pass

    @abstractmethod
    def set_fading_doppler_frequency(self, channel, path, frequency):
        """
        Set the fading doppler frequency.

        :param channel: int, channel number
        :param path: int, path
        :param frequency:  float, doppler frequency
        :return:
        """
        pass

    @abstractmethod
    def query_input_power_level(self, port):
        """
        Query input power level.

        :param port: Union[str, int], input port
        :return: float, power_level dBm
        """
        pass

    @abstractmethod
    def set_input_power_level(self, port, dbm_value):
        """
        Set input power level.

        :param port: Union[str, int], input port
        :param dbm_value: float, power_level dBm
        :return:
        """
        pass

    @abstractmethod
    def query_output_power_level(self, port):
        """
        Query output power level.

        :param port: Union[str, int], output port
        :return: float, power_level dBm
        """
        pass

    @abstractmethod
    def set_output_power_level(self, port, dbm_value):
        """
        Set output power level.

        :param port: Union[str, int], output port
        :param dbm_value: float, power_level dBm
        :return:
        """
        pass

    @abstractmethod
    def load_local_iq_playback_file(self, path):
        """
        Load the IQPlayback file and transfer it to the channel emulator.

        :param path: iq playback file path
        :return:
        """
        pass

    @abstractmethod
    def load_remote_iq_playback_file(self, path):
        """
        Load the IQPlayback file on remote pc.

        :param path: iq playback file path
        :return:
        """
        pass

    @abstractmethod
    def query_iq_playback_status(self):
        """
        Query iq playback status enabled or disabled.

        :return: str, enabled or disabled
        """
        pass

    @abstractmethod
    def enable_iq_playback(self):
        """
        Enable iq playback.

        :return:
        """
        pass

    @abstractmethod
    def disable_iq_playback(self):
        """
        Disable iq playback.

        :return:
        """
        pass

    @abstractmethod
    def set_noise_level(self, port, dbm_value):
        """
        Set the Noise Level for the specified port.

        :param port: Union[str, int], port
        :param dbm_value: float, dBm
        :return:
        """
        pass

    @abstractmethod
    def start_channel_emulation(self):
        """
        Start playing channel emulation.

        :return:
        """
        pass

    @abstractmethod
    def pause_channel_emulation(self):
        """
        Pause playing channel emulation.

        :return:
        """
        pass

    @abstractmethod
    def stop_channel_emulation(self):
        """
        Stop playing channel emulation.

        :return:
        """
        pass

    @abstractmethod
    def query_high_speed_train_ds(self, channel, path):
        """
        Query High Speed Train Ds(m) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :return:
        """
        pass

    @abstractmethod
    def set_high_speed_train_ds(self, channel, path, ds):
        """
        Set High Speed Train Ds(m) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :param ds: float, high speed train ds
        :return:
        """
        pass

    @abstractmethod
    def query_high_speed_train_dmin(self, channel, path):
        """
        Query High Speed Train Dmin(m) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :return:
        """
        pass

    @abstractmethod
    def set_high_speed_train_dmin(self, channel, path, dmin):
        """
        Set High Speed Train Dmin(m) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :param dmin: float, high speed train dmin
        :return:
        """
        pass

    @abstractmethod
    def query_high_speed_train_velocity(self, channel, path):
        """
        Query High Speed Train Velocity(km/h) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :return:
        """
        pass

    @abstractmethod
    def set_high_speed_train_velocity(self, channel, path, velocity):
        """
        Set High Speed Train Velocity(km/h) for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :param velocity: float, high speed train velocity
        :return:
        """
        pass

    @abstractmethod
    def query_high_speed_train_fd(self, channel, path):
        """
        Query High Speed Train fd(Hz)i.e. maximum Doppler for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :return:
        """
        pass

    @abstractmethod
    def set_high_speed_train_fd(self, channel, path, fd):
        """
        Set High Speed Train fd(Hz)i.e. maximum Doppler for the given path of the given channel.

        :param channel: int, start form 1, channel NO
        :param path: int, start form 1, path
        :param fd: float, high speed train fd
        :return:
        """
        pass
